            args.issuer,
            args.key_version,
            args.moment,
        )
        _write_new_durable(output_path, packet)
    except (OSError, UnicodeDecodeError, TypeError, ValueError) as exc:
        return _fail(exc)

    _emit_line(
        {
            "status": "exported",
            "output": output_path,
            "bytes": len(packet),
            "digest": hashlib.sha256(packet).hexdigest(),
        }
    )
    return 0


